let items=seed.map(x=>({...x})),tasks=[],view='收件箱',filter='全部',query='';const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const modes=['全部','只收藏','稍后看或试','学习','待行动'];
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3000)}
function preview(x){return x.url?`<img src="${x.url}" alt="${esc(x.title)}">`:`<div class="preview ${x.type}"><small>${esc(x.source)} · 示例内容</small><strong>${esc(x.headline)}</strong>${x.text.split('\n').slice(0,2).map(t=>`<p>${esc(t)}</p>`).join('')}</div>`}
function matches(x,q){const text=[x.title,x.keys,x.text,x.topic].join(' ').toLowerCase();return !q||q.toLowerCase().split(/\s+/).every(t=>text.includes(t))}
function navigate(v){view=v;filter='全部';query='';$('search').value='';render()}
function search(q){query=q;view='收件箱';filter='全部';$('search').value=q;for(const d of document.querySelectorAll('dialog[open]'))d.close();render()}
function render(){const icons=['▣','▦','◷'];$('nav').innerHTML=['收件箱','主题集合','行动提醒'].map((v,i)=>`<button class="${view===v?'active':''}" data-nav="${v}"><span>${icons[i]}</span>${v}</button>`).join('');$('crumb').textContent=view;$('heading').textContent=view==='主题集合'?'让有关的记忆，在一起。':view==='行动提醒'?'一点一点，把想法用起来。':'每一份收藏，都有回响。';$('subtitle').textContent=view==='行动提醒'?'只跟进你确认过的事。完成、延期或暂停，都由你决定。':'从一个关键词，找回当时想留住的东西。';$('filters').hidden=view!=='收件箱';$('insight')?.removeAttribute('hidden');$('listtitle').textContent=view==='主题集合'?'按主题重逢':view==='行动提醒'?'我的行动':query?`搜索「${query}」`:'最近收下的';$('filters').innerHTML=modes.map(m=>`<button class="${filter===m?'active':''}" data-filter="${m}">${m}</button>`).join('');
if(view==='主题集合'){const topics=[...new Set(items.map(x=>x.topic))];$('count').textContent=topics.length+' 个主题';$('content').innerHTML=`<div class="topics">${topics.map(t=>`<button class="topic" data-query="${esc(t)}"><span class="tag">主题集合</span><b>${esc(t)}</b><p>${items.filter(x=>x.topic===t).length} 份资料 · 点击查看关联内容 ↗</p></button>`).join('')}</div>`;return}
if(view==='行动提醒'){$('count').textContent=tasks.length+' 个行动';$('content').innerHTML=tasks.length?tasks.map(t=>`<article class="task"><span class="tag">${esc(t.status)}</span><h3>${esc(t.title)}</h3><p>${esc(t.priority)} · ${esc(t.when.replace('T',' '))} · ${esc(t.frequency)}</p><button data-open="${t.item}">查看来源</button>${t.status!=='已完成'?`<button data-task="${t.id}" data-status="已完成">✓ 完成</button><button data-task="${t.id}" data-status="延期">延后一天</button><button data-task="${t.id}" data-status="${t.status==='已暂停'?'进行中':'已暂停'}">${t.status==='已暂停'?'恢复':'暂停'}</button>`:''}</article>`).join(''):'<div class="empty"><h2>还没有需要跟进的事</h2><p>打开一张学习截图，确认后创建你的第一条提醒。</p><button data-open="2">用日语口诀试试看</button></div>';return}
const found=items.filter(x=>matches(x,query)&&(filter==='全部'||x.intent===filter));$('count').textContent=found.length+' 份记忆';$('content').innerHTML=found.length?`<div class="grid">${found.map(x=>`<button class="card" data-open="${x.id}">${preview(x)}<div class="cardbody"><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><div class="cardmeta"><span class="tag">${esc(x.intent)}</span><span>${esc(x.source)} · ${x.date}</span></div></div></button>`).join('')}</div>`:'<div class="empty"><h2>暂时没找到这段记忆</h2><p>试试更短的词，例如「歌名」「日语」「耳机」。原型暂不支持真实语义理解。</p><button data-query="">查看全部</button></div>'}
function openDetail(id){const x=items.find(x=>x.id===Number(id));if(!x)return;const rel=items.find(r=>r.id===x.related);$('detailbody').innerHTML=`<div class="modalhead"><h2>${esc(x.title)}</h2><button data-close="detail" aria-label="关闭详情">×</button></div><div class="detailpreview">${preview(x)}</div><p class="muted">${x.url?'本机图片 · 未进行 AI 识别':'示例摘要 · '+esc(x.summary)}</p><h3>内容依据</h3><div class="evidence">${esc(x.text)}</div><label class="field">你想怎样使用它？<select id="intent">${modes.slice(1).map(m=>`<option ${m===x.intent?'selected':''}>${m}</option>`).join('')}</select></label>${rel?`<h3>相关记忆</h3><button class="related" data-open="${rel.id}">${esc(rel.title)} ↗</button><p class="muted">关联依据：都涉及日语语法与动作表达。</p><button id="unlink">解除关联</button>`:''}<button class="full" id="saveintent">保存使用方式</button><button class="primary full" id="remind">确认并安排提醒</button><p class="note">仅演示流程；刷新后恢复初始数据，不会发送真实通知。</p>`;$('saveintent').onclick=()=>{x.intent=$('intent').value;render();toast('已更新保存意图')};if($('unlink'))$('unlink').onclick=()=>{x.related=null;openDetail(x.id);toast('已解除这条关联')};$('remind').onclick=()=>reminder(x);if(!$('detail').open)$('detail').showModal()}
function reminder(x){x.intent=$('intent').value;const now=new Date(Date.now()+86400000);now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('detailbody').innerHTML=`<div class="modalhead"><h2>安排一次温和的提醒</h2><button data-close="detail" aria-label="关闭">×</button></div><p>${esc(x.title)}</p><form id="reminderform"><label class="field">这件事有多重要？<select id="priority"><option>普通 · 有空时做</option><option>重要 · 希望近期完成</option><option>很重要 · 优先处理</option></select></label><label class="field">首次提醒时间<input id="when" type="datetime-local" required value="${now.toISOString().slice(0,16)}"></label><label class="field">跟进频率<select id="frequency"><option>仅提醒一次</option><option>每天一次，直到完成</option><option>每周一次，直到完成</option></select></label><p class="muted">你可以随时完成、延期或暂停。这里只创建演示任务。</p><button type="submit" class="primary full">确认创建提醒</button></form>`;$('reminderform').onsubmit=e=>{e.preventDefault();if(new Date($('when').value)<=new Date()){toast('请选择未来的提醒时间');return}if(tasks.some(t=>t.item===x.id&&t.status!=='已完成')){toast('这份资料已经有待跟进的行动');return}tasks.push({id:Date.now(),item:x.id,title:x.title,priority:$('priority').value,when:$('when').value,frequency:$('frequency').value,status:'进行中'});$('detail').close();navigate('行动提醒');toast('已加入行动列表 · 演示提醒')}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav)navigate(b.dataset.nav);if(b.dataset.filter){filter=b.dataset.filter;render()}if('query'in b.dataset)search(b.dataset.query);if(b.dataset.open)openDetail(b.dataset.open);if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.task){const t=tasks.find(t=>t.id===Number(b.dataset.task));if(b.dataset.status==='延期'){const d=new Date(t.when);d.setDate(d.getDate()+1);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());t.when=d.toISOString().slice(0,16);toast('已延后一天')}else t.status=b.dataset.status;render()}});
$('search').addEventListener('input',e=>{query=e.target.value;view='收件箱';render()});$('import').onclick=()=>$('upload').showModal();$('viewstudy').onclick=()=>search('日语');$('helper').onclick=()=>$('assistantDialog').showModal();$('showtasks').onclick=()=>{$('assistantDialog').close();navigate('行动提醒')};$('sample').onclick=()=>{$('upload').close();openDetail(2);toast('已打开日语示例：体验意图、关联和提醒')};
function importFiles(files){let n=0;for(const f of files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024){toast('仅支持 10 MB 以内的 PNG、JPG、WebP 图片');continue}items.unshift({id:Date.now()+n, title:f.name,url:URL.createObjectURL(f),type:'',source:'本机导入',topic:'未分类',intent:'只收藏',date:'刚刚',text:'尚未识别。原型只预览图片；可按文件名搜索。',summary:'仅当前页面可见，未上传或调用 AI。',keys:f.name});n++}if(n){$('upload').close();navigate('收件箱');toast(`已预览 ${n} 张图片 · 未上传`)}$('files').value=''}$('files').onchange=e=>importFiles(e.target.files);$('drop').ondragover=e=>e.preventDefault();$('drop').ondrop=e=>{e.preventDefault();importFiles(e.dataTransfer.files)};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('search').focus()}});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_memory_demo',description:'Search demo memories by keyword and show matching cards; does not perform AI semantic search.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.query!=='string')throw new Error('query must be a string');search(input.query);return{matches:items.filter(x=>matches(x,input.query)).map(x=>({id:x.id,title:x.title}))}}})).catch(()=>{})}catch{}}
